const normalize=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,'');
const humanize=(value:string)=>value.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[._:-]+/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase());
const pageLabel=(page:Pick<StorefrontBuilderPageListItem,'pageKey'|'pageType'>|Pick<StorefrontPageDocument,'pageKey'|'pageType'>)=>PAGE_LABELS[normalize(page.pageType||page.pageKey)]??humanize(page.pageType||page.pageKey);
const fieldLabel=(key:string)=>FIELD_LABELS[normalize(key)]??humanize(key);
const componentLabel=(key:string)=>COMPONENT_LABELS[key]??humanize(key.split('.').at(-1)??key);
const optionLabel=(value:string)=>OPTION_LABELS[value]??humanize(value);
const iconFor=(key:string):VisualBuilderIconName=>{const value=key.toLowerCase();if(value.includes('header'))return'header';if(value.includes('footer'))return'footer';if(value.includes('image')||value.includes('gallery')||value.includes('video'))return'image';if(value.includes('navigation')||value.includes('menu'))return'menu';if(value.includes('text')||value.includes('heading')||value.includes('copy'))return'text';if(value.includes('product')||value.includes('collection'))return'box';if(value.includes('review'))return'star';if(value.includes('hero')||value.includes('section')||value.includes('layout'))return'layout';return'component'};
const groupFor=(key:string)=>{const value=key.toLowerCase();if(value.includes('cart')||value.includes('finder')||value.includes('recipe')||value.includes('shop-the-look'))return'Interaktív kereskedelem';if(value.includes('product')||value.includes('collection')||value.includes('recommend')||value.includes('cta'))return'Kereskedelem';if(value.includes('image')||value.includes('gallery')||value.includes('video'))return'Média';if(value.includes('navigation')||value.includes('menu')||value.includes('header')||value.includes('footer'))return'Navigáció';if(value.includes('review')||value.includes('editorial')||value.includes('text')||value.includes('heading'))return'Tartalom';if(value.includes('section')||value.includes('container')||value.includes('grid')||value.includes('stack')||value.includes('button'))return'Alap elemek';return'Egyéb'};
const responsiveModeLabel=(mode:string)=>mode==='fixed'?'Fix elem':mode==='grid'?'Rugalmas rács':mode==='stack'?'Egymás alá rendeződik':'Reszponzív';
