  const preview=()=>{if(!pageId||!draftRevision)return;run(async()=>{if(dirty)throw new Error('Előnézet előtt mentsd a módosításokat.');const result=await createVisualBuilderPreviewAction({pageId,revisionNumber:draftRevision,operationKey:operationKey('preview')});window.open(`${result.href}?viewport=${viewport}`,'_blank','noopener,noreferrer');setNotice(`Előnézet létrehozva · r${result.revisionNumber}`)})};
  const publish=()=>{if(!pageId||!draftRevision)return;run(async()=>{if(dirty)throw new Error('Közzététel előtt mentsd a módosításokat.');const result=await publishVisualBuilderPageAction({pageId,expectedDraftRevision:draftRevision,operationKey:operationKey('publish')});setPublishedRevision(result.revisionNumber);setPublishOpen(false);setNotice(`Közzétéve · r${result.revisionNumber}`);router.refresh()})};
