      {panelMode==='saved'?<StorefrontOwnBlocksPanel document={document} selectedNode={selected} selectedIsTopLevel={selectedFlat?.parentId===null} initialSavedBlocks={savedBlocks} capability={capability} onApply={(next,nodeId,message)=>applyExternal(next,message,nodeId)}/>:null}
